proc setMemoryFunctions*(_: type SDL3; malloc_func: SDL_malloc_func; calloc_func: SDL_calloc_func; realloc_func: SDL_realloc_func; free_func: SDL_free_func): bool {.importc: "SDL_SetMemoryFunctions", cdecl.}
