  ##
  ## \sa SDL_UnsetEnvironmentVariable
proc qsort*(_: type SDL3; base: pointer; nmemb: csize_t; size: csize_t; compare: SDL_CompareCallback) {.importc: "SDL_qsort", cdecl.}
  ## Sort an array.
  ##
  ## For example:
  ##
  ## ```c
  ## typedef struct {
  ##     int key;
  ##     const char *string;
  ## } data;
  ##
  ## int SDLCALL compare(const void *a, const void *b)
  ## {
  ##     const data *A = (const data *)a;
  ##     const data *B = (const data *)b;
  ##
  ##     if (A->n < B->n) {
  ##         return -1;
  ##     } else if (B->n < A->n) {
  ##         return 1;
  ##     } else {
  ##         return 0;
  ##     }
  ## }
  ##
  ## data values[] = {
  ##     { 3, "third" }, { 1, "first" }, { 2, "second" }
  ## };
  ##
  ## SDL_qsort(values, SDL_arraysize(values), sizeof(values[0]), compare);
  ## ```
  ##
  ## \param base a pointer to the start of the array.
  ## \param nmemb the number of elements in the array.
  ## \param size the size of the elements in the array.
  ## \param compare a function used to compare elements in the array.
  ##
  ## \threadsafety It is safe to call this function from any thread.
  ##
  ## \since This function is available since SDL 3.2.0.
  ##
  ## \sa SDL_bsearch
  ## \sa SDL_qsort_r
proc bsearch*(_: type SDL3; key: pointer; base: pointer; nmemb: csize_t; size: csize_t; compare: SDL_CompareCallback): pointer {.importc: "SDL_bsearch", cdecl.}
  ## Perform a binary search on a previously sorted array.
  ##
  ## For example:
  ##
  ## ```c
  ## typedef struct {
  ##     int key;
  ##     const char *string;
  ## } data;
  ##
  ## int SDLCALL compare(const void *a, const void *b)
  ## {
  ##     const data *A = (const data *)a;
  ##     const data *B = (const data *)b;
  ##
  ##     if (A->n < B->n) {
  ##         return -1;
  ##     } else if (B->n < A->n) {
  ##         return 1;
  ##     } else {
  ##         return 0;
  ##     }
  ## }
  ##
  ## data values[] = {
  ##     { 1, "first" }, { 2, "second" }, { 3, "third" }
  ## };
  ## data key = { 2, NULL };
  ##
  ## data *result = SDL_bsearch(&key, values, SDL_arraysize(values), sizeof(values[0]), compare);
  ## ```
  ##
  ## \param key a pointer to a key equal to the element being searched for.
  ## \param base a pointer to the start of the array.
  ## \param nmemb the number of elements in the array.
  ## \param size the size of the elements in the array.
  ## \param compare a function used to compare elements in the array.
  ## \returns a pointer to the matching element in the array, or NULL if not
  ##          found.
  ##
  ## \threadsafety It is safe to call this function from any thread.
  ##
  ## \since This function is available since SDL 3.2.0.
  ##
  ## \sa SDL_bsearch_r
  ## \sa SDL_qsort
proc qsort_r*(_: type SDL3; base: pointer; nmemb: csize_t; size: csize_t; compare: SDL_CompareCallback_r; userdata: pointer) {.importc: "SDL_qsort_r", cdecl.}
  ## Sort an array, passing a userdata pointer to the compare function.
  ##
  ## For example:
  ##
  ## ```c
  ## typedef enum {
  ##     sort_increasing,
  ##     sort_decreasing,
  ## } sort_method;
  ##
  ## typedef struct {
  ##     int key;
  ##     const char *string;
  ## } data;
  ##
  ## int SDLCALL compare(const void *userdata, const void *a, const void *b)
  ## {
  ##     sort_method method = (sort_method)(uintptr_t)userdata;
  ##     const data *A = (const data *)a;
  ##     const data *B = (const data *)b;
  ##
  ##     if (A->key < B->key) {
  ##         return (method == sort_increasing) ? -1 : 1;
  ##     } else if (B->key < A->key) {
  ##         return (method == sort_increasing) ? 1 : -1;
  ##     } else {
  ##         return 0;
  ##     }
  ## }
  ##
  ## data values[] = {
  ##     { 3, "third" }, { 1, "first" }, { 2, "second" }
  ## };
  ##
  ## SDL_qsort_r(values, SDL_arraysize(values), sizeof(values[0]), compare, (const void *)(uintptr_t)sort_increasing);
  ## ```
  ##
  ## \param base a pointer to the start of the array.
  ## \param nmemb the number of elements in the array.
  ## \param size the size of the elements in the array.
  ## \param compare a function used to compare elements in the array.
  ## \param userdata a pointer to pass to the compare function.
  ##
  ## \threadsafety It is safe to call this function from any thread.
  ##
  ## \since This function is available since SDL 3.2.0.
  ##
  ## \sa SDL_bsearch_r
  ## \sa SDL_qsort
proc bsearch_r*(_: type SDL3; key: pointer; base: pointer; nmemb: csize_t; size: csize_t; compare: SDL_CompareCallback_r; userdata: pointer): pointer {.importc: "SDL_bsearch_r", cdecl.}
  ## Perform a binary search on a previously sorted array, passing a userdata
  ## pointer to the compare function.
  ##
  ## For example:
  ##
  ## ```c
  ## typedef enum {
  ##     sort_increasing,
  ##     sort_decreasing,
  ## } sort_method;
  ##
  ## typedef struct {
  ##     int key;
  ##     const char *string;
  ## } data;
  ##
  ## int SDLCALL compare(const void *userdata, const void *a, const void *b)
  ## {
  ##     sort_method method = (sort_method)(uintptr_t)userdata;
  ##     const data *A = (const data *)a;
  ##     const data *B = (const data *)b;
  ##
  ##     if (A->key < B->key) {
  ##         return (method == sort_increasing) ? -1 : 1;
  ##     } else if (B->key < A->key) {
  ##         return (method == sort_increasing) ? 1 : -1;
  ##     } else {
  ##         return 0;
  ##     }
  ## }
  ##
  ## data values[] = {
  ##     { 1, "first" }, { 2, "second" }, { 3, "third" }
  ## };
  ## data key = { 2, NULL };
  ##
  ## data *result = SDL_bsearch_r(&key, values, SDL_arraysize(values), sizeof(values[0]), compare, (const void *)(uintptr_t)sort_increasing);
  ## ```
  ##
  ## \param key a pointer to a key equal to the element being searched for.
  ## \param base a pointer to the start of the array.
  ## \param nmemb the number of elements in the array.
  ## \param size the size of the elements in the array.
  ## \param compare a function used to compare elements in the array.
  ## \param userdata a pointer to pass to the compare function.
  ## \returns a pointer to the matching element in the array, or NULL if not
  ##          found.
  ##
  ## \threadsafety It is safe to call this function from any thread.
  ##
  ## \since This function is available since SDL 3.2.0.
  ##
  ## \sa SDL_bsearch
  ## \sa SDL_qsort_r
proc abs*(_: type SDL3; x: cint): cint {.importc: "SDL_abs", cdecl.}
  ## Compute the absolute value of `x`.
