  ## \sa SDL_round
  ## \sa SDL_lroundf
  ## \sa SDL_floorf
  ## \sa SDL_ceilf
  ## \sa SDL_truncf
proc lround*(_: type SDL3; x: cdouble): clong {.importc: "SDL_lround", cdecl.}
  ## Round `x` to the nearest integer representable as a long
